const reportWarmupAt = `-- name: ReportWarmupAt :many
SELECT w.provider_id, w.start_date, w.days, w.engaged_first, w.status
FROM warmup_plans w
WHERE w.provider_id = ANY($1::uuid[])
ORDER BY w.created_at DESC
`

type ReportWarmupAtRow struct {
	ProviderID   uuid.UUID `json:"providerId"`
	StartDate    time.Time `json:"startDate"`
	Days         int32     `json:"days"`
	EngagedFirst bool      `json:"engagedFirst"`
	Status       string    `json:"status"`
}

// Warm-up plans of the campaign's providers (the day each was on when the
// campaign was sent).
func (q *Queries) ReportWarmupAt(ctx context.Context, providerIds []uuid.UUID) ([]ReportWarmupAtRow, error) {
	rows, err := q.db.Query(ctx, reportWarmupAt, providerIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportWarmupAtRow{}
	for rows.Next() {
		var i ReportWarmupAtRow
		if err := rows.Scan(
			&i.ProviderID,
			&i.StartDate,
			&i.Days,
			&i.EngagedFirst,
			&i.Status,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
